package com.aaliyun.leadnews.schedule.domain;
import com.aaliyun.leadnews.common.persistence.BaseEntity;import com.baomidou.mybatisplus.annotation.*;import java.time.LocalDateTime;
@TableName("schedule_task")public class ScheduleTask extends BaseEntity{@TableId(type=IdType.AUTO)private Long id;private String taskType;private Long businessId;private LocalDateTime executeTime;private String status;private Integer retryCount;private String payload;private String lastError;private LocalDateTime startedTime;public Long getId(){return id;}public String getTaskType(){return taskType;}public void setTaskType(String v){taskType=v;}public Long getBusinessId(){return businessId;}public void setBusinessId(Long v){businessId=v;}public LocalDateTime getExecuteTime(){return executeTime;}public void setExecuteTime(LocalDateTime v){executeTime=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Integer getRetryCount(){return retryCount;}public void setRetryCount(Integer v){retryCount=v;}public String getPayload(){return payload;}public void setPayload(String v){payload=v;}public String getLastError(){return lastError;}public void setLastError(String v){lastError=v;}public LocalDateTime getStartedTime(){return startedTime;}public void setStartedTime(LocalDateTime v){startedTime=v;}}
